  1→// Package filter provides clean/smudge transcript filtering for path normalization.
  2→// Transcripts stored in checkpoints contain absolute paths (repo root, home directory)
  3→// which are machine-specific. This package normalizes paths on store (clean) and
  4→// restores them on read (smudge), similar to git's clean/smudge filter pipeline.
  5→package filter
  6→
  7→import (
  8→	"bytes"
  9→
 10→	"github.com/entireio/cli/cmd/entire/cli/settings"
 11→)
 12→
 13→// Filter defines a single find-and-replace pair used during clean/smudge.
 14→// Clean replaces Match with Replace; Smudge reverses the substitution.
 15→type Filter struct {
 16→	Match   string // literal string to find
 17→	Replace string // literal string to substitute
 18→}
 19→
 20→// Clean applies the filter in the "store" direction: Match → Replace.
 21→func (f Filter) Clean(data []byte) []byte {
 22→	return bytes.ReplaceAll(data, []byte(f.Match), []byte(f.Replace))
 23→}
 24→
 25→// Smudge applies the filter in the "restore" direction: Replace → Match.
 26→func (f Filter) Smudge(data []byte) []byte {
 27→	return bytes.ReplaceAll(data, []byte(f.Replace), []byte(f.Match))
 28→}
 29→
 30→// Pipeline holds an ordered list of filters and applies them collectively.
 31→// A nil *Pipeline is safe to use — all methods are no-ops.
 32→type Pipeline struct {
 33→	filters []Filter
 34→}
 35→
 36→// NewPipeline creates a filter pipeline with built-in path filters and optional user filters.
 37→// Built-in filters (applied first, most-specific first):
 38→//  1. repoRoot → __ent__/repo
 39→//  2. homeDir  → __ent__/home
 40→//
 41→// User filters are appended after built-ins.
 42→func NewPipeline(repoRoot, homeDir string, userFilters []settings.TranscriptFilter) (*Pipeline, error) {
 43→	var filters []Filter
 44→
 45→	// Built-in filters, most-specific first (repo root before home dir,
 46→	// since repo root is typically under home dir).
 47→	if repoRoot != "" {
 48→		f := Filter{Match: repoRoot, Replace: "__ent__/repo"}
 49→		if err := ValidateFilter(f, true); err != nil {
 50→			return nil, err
 51→		}
 52→		filters = append(filters, f)
 53→	}
 54→	if homeDir != "" {
 55→		f := Filter{Match: homeDir, Replace: "__ent__/home"}
 56→		if err := ValidateFilter(f, true); err != nil {
 57→			return nil, err
 58→		}
 59→		filters = append(filters, f)
 60→	}
 61→
 62→	// User filters
 63→	for _, uf := range userFilters {
 64→		f := Filter{
 65→			Match:   uf.Match,
 66→			Replace: "__ent_user__/" + uf.Key,
 67→		}
 68→		if err := ValidateFilter(f, false); err != nil {
 69→			return nil, err
 70→		}
 71→		filters = append(filters, f)
 72→	}
 73→
 74→	return &Pipeline{filters: filters}, nil
 75→}
 76→
 77→// Clean applies all filters in order (store direction).
 78→// Safe to call on a nil *Pipeline (returns data unchanged).
 79→func (p *Pipeline) Clean(data []byte) []byte {
 80→	if p == nil {
 81→		return data
 82→	}
 83→	for _, f := range p.filters {
 84→		data = f.Clean(data)
 85→	}
 86→	return data
 87→}
 88→
 89→// Smudge applies all filters in reverse order (restore direction).
 90→// Safe to call on a nil *Pipeline (returns data unchanged).
 91→func (p *Pipeline) Smudge(data []byte) []byte {
 92→	if p == nil {
 93→		return data
 94→	}
 95→	for i := len(p.filters) - 1; i >= 0; i-- {
 96→		data = p.filters[i].Smudge(data)
 97→	}
 98→	return data
 99→}
100→
101→// CleanString applies Clean to a string value.
102→// Safe to call on a nil *Pipeline (returns s unchanged).
103→func (p *Pipeline) CleanString(s string) string {
104→	if p == nil {
105→		return s
106→	}
107→	return string(p.Clean([]byte(s)))
108→}
109→
110→// SmudgeString applies Smudge to a string value.
111→// Safe to call on a nil *Pipeline (returns s unchanged).
112→func (p *Pipeline) SmudgeString(s string) string {
113→	if p == nil {
114→		return s
115→	}
116→	return string(p.Smudge([]byte(s)))
117→}
