 737→+// ValidateFilter checks that a filter is well-formed.
 738→+// isBuiltIn distinguishes built-in filters (whose replacements start with __ent__/)
 739→+// from user filters (whose replacements must start with __ent_user__/).
 740→+func ValidateFilter(f Filter, isBuiltIn bool) error {
 741→+	if f.Match == "" {
 742→+		return errors.New("filter match must be non-empty")
 743→+	}
 744→+	if f.Replace == "" {
 745→+		return errors.New("filter replace must be non-empty")
 746→+	}
 747→+	if f.Match == f.Replace {
 748→+		return errors.New("filter match and replace must be different")
 749→+	}
 750→+
 751→+	// Idempotency: applying clean twice must produce the same result.
 752→+	// This means the replacement string must not itself contain the match pattern,
 753→+	// AND the match string must not contain the replacement pattern (which would
 754→+	// cause smudge to corrupt the match).
 755→+	if strings.Contains(f.Replace, f.Match) {
 756→+		return fmt.Errorf("filter replace %q must not contain match %q (not idempotent)", f.Replace, f.Match)
 757→+	}
 758→+	if strings.Contains(f.Match, f.Replace) {
 759→+		return fmt.Errorf("filter match %q must not contain replace %q (smudge would corrupt)", f.Match, f.Replace)
 760→+	}
 761→+
 762→+	if isBuiltIn {
 763→+		if !strings.HasPrefix(f.Replace, builtInPrefix) {
 764→+			return fmt.Errorf("built-in filter replace must start with %q, got %q", builtInPrefix, f.Replace)
 765→+		}
 766→+		if len(f.Match) < minBuiltInMatchLen {
 767→+			return fmt.Errorf("built-in filter match must be at least %d characters, got %d", minBuiltInMatchLen, len(f.Match))
 768→+		}
 769→+	} else {
 770→+		if !strings.HasPrefix(f.Replace, userPrefix) {
 771→+			return fmt.Errorf("user filter replace must start with %q, got %q", userPrefix, f.Replace)
 772→+		}
 773→+		if len(f.Match) < minUserMatchLen {
 774→+			return fmt.Errorf("user filter match must be at least %d characters, got %d", minUserMatchLen, len(f.Match))
 775→+		}
 776→+	}
 777→+
 778→+	return nil
 779→+}
